export function Discoverability({
  labelled = {{labelled}},
  tooltip = {{tooltip}},
  icon = "{{icon}}",
  accent = "{{accent}}",
}) {
  const paths = {
    filter: "M3 5h18v2l-7 8v5l-4-2v-3L3 7z",
    export: "M12 3l5 5h-3v7h-4V8H7z",
    share: "M18 8a3 3 0 1 0-2.8-4H15a3 3 0 0 0 .2 2.4L9 9.7A3 3 0 1 0 9 14.3l6.2 3.3A3 3 0 1 0 15 15l-6-3.2a3 3 0 0 0 0-1.6L15 7a3 3 0 0 0 3 1z",
  };
  return (
    <div style={{ position: "relative", width: "100%", maxWidth: 320, padding: 26, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa", textAlign: "center" }}>
      <button type="button" style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "#fff", border: "1.5px solid #24143022", borderRadius: 8, padding: "8px 12px", cursor: "pointer", color: accent }}>
        <svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d={paths[icon]} /></svg>
        {labelled && <span style={{ textTransform: "capitalize", fontWeight: 600, color: "#241430" }}>{icon}</span>}
      </button>
      {tooltip && <span style={{ display: "block", marginTop: 8, fontSize: 11, background: "#241430", color: "#fff", borderRadius: 6, padding: "4px 8px", textTransform: "capitalize" }}>{icon}</span>}
      <p style={{ margin: "14px 0 0" }}>{labelled ? "Labelled" : "Icon-only"}{tooltip ? " + tooltip" : ""} &mdash; toggle to compare how easily this is found</p>
    </div>
  );
}
